#!/usr/bin/env python3
from pathlib import Path
import re
import sys

p=Path(sys.argv[1] if len(sys.argv)>1 else 'app/src/main/assets/admin/index.html')
s=p.read_text(encoding='utf-8')
MARKER='JAYUMINTON_GAME_REPORT_EXACT_MASCOT_LAYOUT_V20902'
if MARKER in s:
    print('ADMIN_GAME_REPORT_EXACT_MASCOT_LAYOUT_V20902_ALREADY_OK'); raise SystemExit(0)
for token in ('JAYUMINTON_GAME_REPORT_VISUAL_FIX_V20900','JAYUMINTON_GAME_REPORT_EXPAND_EXPORT_V20901','window.__JAYUMINTON_GAME_REPORT_V20895__'):
    if token not in s: raise SystemExit('v209.02 prerequisite missing: '+token)

# Use the exact mascot image supplied by the user. The source screenshot was only
# cropped and its connected white background made transparent; the mascot itself
# is not redrawn or substituted.
DOG_URI='data:image/png;base64,'
s,n=re.subn(r"var DOG='data:image/[^']+',SHUTTLE=",lambda m:"var DOG='"+DOG_URI+"',SHUTTLE=",s,count=1)
if n!=1: raise SystemExit('v209.02 DOG source anchor mismatch')

STYLE=r"""
<style id="jmReportExactMascotLayoutV20902Style">
/* JAYUMINTON_GAME_REPORT_EXACT_MASCOT_LAYOUT_V20902_CSS */

/* The loose shuttlecock at the top was visually dirty and overlapped the header. */
.j98-shuttle{display:none!important;visibility:hidden!important}

/* Exact supplied doodle dog. Keep the whole silhouette visible. */
.j98-dog-top{
  display:block!important;right:2.8%!important;top:17.2%!important;
  width:11.5%!important;min-width:72px!important;max-width:104px!important;
  height:auto!important;transform:none!important;clip-path:none!important;
  object-fit:contain!important;opacity:1!important;
  filter:drop-shadow(0 3px 3px rgba(5,60,72,.10))!important;z-index:9!important;
}
/* Existing racket is retained and moved into the raised paw area. */
.j100-racket-held{
  display:block!important;right:8.0%!important;top:12.2%!important;
  width:7.2%!important;min-width:48px!important;max-width:69px!important;
  transform:rotate(-8deg)!important;z-index:8!important;
}

/* Remove the unnecessary empty lower half of the four summary cards. */
.j95-sum{align-items:start!important}
.j95-card{
  min-height:116px!important;padding:14px 15px 11px!important;
  align-self:start!important;
}
.j95-card strong{margin-top:9px!important}

/* Restore the lower mascot cleanly: no clipping, no white fragment. */
.j98-dog-bottom{
  display:block!important;right:2.7%!important;bottom:5px!important;
  width:76px!important;min-width:0!important;max-width:76px!important;
  height:auto!important;transform:none!important;clip-path:none!important;
  object-fit:contain!important;opacity:1!important;
  filter:drop-shadow(0 3px 3px rgba(5,60,72,.10))!important;z-index:9!important;
}
.j95-footer{overflow:visible!important}

/* Keep report action buttons fully above the native quick menu. */
.j95-actions{
  bottom:92px!important;z-index:2147482000!important;
  background:rgba(218,248,234,.98)!important;
  padding-bottom:9px!important;
}
#pairStatisticsModal .pair-statistics-modal{overflow:auto!important}

@media(max-width:720px){
  .j98-dog-top{right:2.5%!important;top:16.8%!important;width:15%!important;min-width:58px!important;max-width:78px!important}
  .j100-racket-held{right:8.8%!important;top:12.0%!important;width:9.2%!important;min-width:40px!important;max-width:54px!important}
  .j95-card{min-height:90px!important;padding:10px 8px 7px!important}
  .j95-card strong{margin-top:6px!important}
  .j98-dog-bottom{right:2.4%!important;bottom:4px!important;width:64px!important;max-width:64px!important}
  .j95-actions{bottom:82px!important}
}
</style>
"""

SCRIPT=r"""
<script id="jayumintonGameReportExactMascotV20902Script">
/* JAYUMINTON_GAME_REPORT_EXACT_MASCOT_LAYOUT_V20902 */
(function(){'use strict';
var EXACT_DOG='data:image/png;base64,';
function apply(){
  var p=document.getElementById('j95Poster');if(!p)return;
  p.setAttribute('data-jm-style','209.02');
  p.querySelectorAll('.j98-dog-top,.j98-dog-bottom').forEach(function(n){
    if(n.getAttribute('src')!==EXACT_DOG)n.setAttribute('src',EXACT_DOG);
  });
}
function install(){
  var api=window.__JAYUMINTON_GAME_REPORT_V20895__;
  if(api&&typeof api.render==='function'&&!api.render.__jmV20902){
    var base=api.render;
    function wrapped(){
      var r=base.apply(this,arguments);
      apply();requestAnimationFrame(apply);setTimeout(apply,80);
      return r;
    }
    wrapped.__jmV20902=true;wrapped.__jmBase=base;
    api.render=wrapped;window.renderPairStatistics=wrapped;window.renderMdPairStatistics=wrapped;
  }
  apply();
}
install();
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});
setTimeout(install,60);setTimeout(install,550);setTimeout(install,1500);setTimeout(apply,2600);
})();
</script>
"""

if '</head>' not in s or '</body>' not in s: raise SystemExit('v209.02 html anchors missing')
s=s.replace('</head>',STYLE+'\n</head>',1)
s=s.replace('</body>',SCRIPT+'\n</body>',1)

for token in (MARKER,'JAYUMINTON_GAME_REPORT_EXACT_MASCOT_LAYOUT_V20902_CSS',
              'jayumintonGameReportExactMascotV20902Script','data-jm-style','209.02',
              '.j98-shuttle{display:none!important','clip-path:none!important',
              'bottom:92px!important','min-height:116px!important',DOG_URI[:64]):
    if token not in s: raise SystemExit('v209.02 contract missing: '+token)

p.write_text(s,encoding='utf-8')
print('ADMIN_GAME_REPORT_EXACT_MASCOT_LAYOUT_V20902_OK')
